pragma solidity ^0.8.24;

interface ICmsnERC20Metadata {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function decimals() external view returns (uint8);
}

interface ICmsnFistSwapFactory {
    function getPair(address tokenA, address tokenB) external view returns (address);
    function createPair(address tokenA, address tokenB) external returns (address pair);
}

interface ICmsnFistSwapRouter {
    function factory() external view returns (address);

    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;
}

interface ICmsnFistSwapPair is ICmsnERC20Metadata {
    function totalSupply() external view returns (uint256);
    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
    function price0CumulativeLast() external view returns (uint256);
    function price1CumulativeLast() external view returns (uint256);
}

contract CmsnFeeReceiver {
    address public immutable owner;

    constructor(address owner_) {
        require(owner_ != address(0), "RECEIVER_OWNER_ZERO");
        owner = owner_;
    }

    function sweep(address token, address to, uint256 amount) external {
        require(msg.sender == owner, "NOT_RECEIVER_OWNER");
        require(to != address(0), "RECEIVER_TO_ZERO");
        (bool success, bytes memory data) =
            token.call(abi.encodeWithSelector(ICmsnERC20Metadata.transfer.selector, to, amount));
        require(success && (data.length == 0 || abi.decode(data, (bool))), "RECEIVER_TRANSFER_FAILED");
    }
}

contract Cmsn {
    struct Account {
        uint256 eligibleLP;
        uint256 pendingLP;
        uint256 pendingUnlockAt;
        uint256 rewardIndexPaid;
        uint256 pendingRewards;
    }

    struct RewardStatus {
        uint256 tokenBalance;
        uint256 lpBalance;
        uint256 eligibleLP;
        uint256 pendingLP;
        uint256 pendingUnlockAt;
        uint256 pendingRewards;
        uint256 recordedLP;
        bool tracked;
        bool inQueue;
        bool canRegister;
        bool canActivate;
        bool shouldRemove;
        uint256 claimable;
        bool rewardExcluded;
    }

    string public constant name = "Cmsn";
    string public constant symbol = "CMSN";
    uint8 public constant decimals = 18;

    uint256 public constant totalSupply = 1737e18;
    uint256 public constant ACC_PRECISION = 1e36;
    uint256 public constant FEE_DENOMINATOR = 10_000;
    uint256 public constant FISTSWAP_HELPER_FORWARD_TOLERANCE_BPS = 500;
    uint256 private constant AUTO_PROCESS_GAS_RESERVE = 80_000;

    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;
    address public constant FISTSWAP_SINGLE_TAX_HELPER = 0xf350972357CfD2E53580e1e3A8CF4D043E921900;

    uint256 private constant Q112 = 2 ** 112;

    ICmsnFistSwapRouter public immutable router;
    ICmsnERC20Metadata public immutable rewardToken;
    ICmsnERC20Metadata public immutable quoteToken;
    ICmsnFistSwapPair public immutable fistUsdtPair;
    CmsnFeeReceiver public immutable feeReceiver;
    address public immutable lpPair;
    uint8 public immutable rewardTokenDecimals;
    uint8 public immutable quoteTokenDecimals;
    bool public immutable usePrice0CumulativeForFistUsdt;

    address public owner;
    address public marketingWallet;
    bool public tradingEnabled;
    bool public swapEnabled = true;
    bool public feesEnabled = true;
    bool public transferTaxEnabled = true;
    bool public ammTaxEnabled = true;
    uint256 public liquidityAddedAt;

    uint256 public NORMAL_BURN_BPS = 100;
    uint256 public NORMAL_MARKETING_BPS = 200;
    uint256 public NORMAL_REWARD_BPS = 200;
    uint256 public LAUNCH_BUY_FEE_BPS = 500;
    uint256 public LAUNCH_SELL_FEE_BPS = 2_500;
    uint256 public LAUNCH_DURATION = 30 minutes;
    uint256 public SWAP_THRESHOLD = 1e18;
    uint256 public MAX_SWAP_PER_PROCESS = 1e18;
    uint256 public MANUAL_PROCESS_COOLDOWN = 1 minutes;
    uint256 public MIN_LP_USD_E18 = 100e18;
    uint256 public MIN_HOLDING_TOKEN_AMOUNT = 0.01e18;
    uint256 public ACTIVATION_DELAY = 30 minutes;
    uint256 public ADDITIONAL_LP_DELAY = 1 minutes;
    uint256 public FIST_USDT_TWAP_PERIOD = 30 minutes;
    uint256 public CMSN_FIST_LP_TWAP_PERIOD = 5 minutes;
    uint256 public SWAP_MIN_OUT_BPS = 7_000;

    uint256 public pendingFeeTokens;
    uint256 public totalEligibleLP;
    uint256 public accRewardPerShare;
    uint256 public accountedRewardBalance;
    uint256 public redirectedRewards;
    uint256 public fistUsdtPriceCumulativeLast;
    uint32 public fistUsdtBlockTimestampLast;
    uint256 public fistUsdPriceE18;
    uint256 public lastFistUsdtTwapUpdateTimestamp;
    uint256 public cmsnFistLpFistPerLpCumulative;
    uint32 public cmsnFistLpObservationTimestampLast;
    uint256 public cmsnFistLpFistPerLpLastE18;
    uint256 public cmsnFistLpTwapCumulativeLast;
    uint32 public cmsnFistLpTwapTimestampLast;
    uint256 public cmsnFistLpFistPerLpTwapE18;
    uint256 public lastCmsnFistLpTwapUpdateTimestamp;
    uint256 public rewardAuditCursor;
    uint256 public fistSwapHelperForwardCredit;
    uint256 public lastManualProcessFeesAt;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => bool) public isFeeExempt;
    mapping(address => bool) public isRewardExcluded;
    mapping(address => Account) public accounts;
    mapping(address => bool) public inRewardAuditQueue;
    address[] public rewardAuditQueue;

    uint256 private unlocked = 1;
    bool private inSwap;

    event Transfer(address indexed from, address indexed to, uint256 amount);
    event Approval(address indexed owner, address indexed spender, uint256 amount);
    event OwnershipTransferred(address indexed oldOwner, address indexed newOwner);
    event MarketingWalletUpdated(address indexed oldWallet, address indexed newWallet);
    event FeeExemptUpdated(address indexed account, bool exempt);
    event TradingEnabled(uint256 liquidityAddedAt);
    event SwapEnabledUpdated(bool enabled);
    event RewardExcludedUpdated(address indexed account, bool excluded);
    event RewardAuditQueued(address indexed user);
    event RewardAuditQueueCompacted(uint256 checked, uint256 removed, uint256 newLength);
    event FeeReceiverDeployed(address indexed receiver);
    event FeesProcessed(uint256 feeTokens, uint256 marketingFist, uint256 rewardFist);
    event PendingRegistered(address indexed user, uint256 amount, uint256 unlockAt);
    event PendingIncreased(address indexed user, uint256 amount, uint256 totalPending, uint256 unlockAt);
    event PendingReduced(address indexed user, uint256 amount, uint256 remainingPending);
    event Activated(address indexed user, uint256 amount, uint256 totalEligible);
    event EligibleReduced(address indexed user, uint256 oldEligible, uint256 newEligible);
    event Removed(address indexed user, uint256 forfeitedReward, string reason);
    event RewardsSynced(uint256 amount, uint256 indexDelta);
    event RewardsRedirected(uint256 amount);
    event Claimed(address indexed user, uint256 amount, address indexed caller);
    event FistUsdtTwapUpdated(uint256 fistUsdPriceE18, uint256 timeElapsed);
    event CmsnFistLpTwapUpdated(uint256 fistPerLpE18, uint256 timeElapsed);

    modifier onlyOwner() {
        require(msg.sender == owner, "NOT_OWNER");
        _;
    }

    modifier nonReentrant() {
        require(unlocked == 1, "REENTRANT");
        unlocked = 2;
        _;
        unlocked = 1;
    }

    constructor(
        address router_,
        address rewardToken_,
        address quoteToken_,
        address fistUsdtPair_,
        address marketingWallet_
    ) {
        require(router_ != address(0), "ROUTER_ZERO");
        require(rewardToken_ != address(0), "FIST_ZERO");
        require(quoteToken_ != address(0), "QUOTE_ZERO");
        require(fistUsdtPair_ != address(0), "FIST_USDT_PAIR_ZERO");
        require(marketingWallet_ != address(0), "MARKETING_ZERO");
        require(marketingWallet_ != FISTSWAP_SINGLE_TAX_HELPER, "HELPER_NOT_FEE_EXEMPT");

        router = ICmsnFistSwapRouter(router_);
        rewardToken = ICmsnERC20Metadata(rewardToken_);
        quoteToken = ICmsnERC20Metadata(quoteToken_);
        fistUsdtPair = ICmsnFistSwapPair(fistUsdtPair_);
        feeReceiver = new CmsnFeeReceiver(address(this));
        marketingWallet = marketingWallet_;
        owner = msg.sender;

        address factory = router.factory();
        require(factory != address(0), "FACTORY_ZERO");
        address pair = ICmsnFistSwapFactory(factory).getPair(address(this), rewardToken_);
        if (pair == address(0)) {
            pair = ICmsnFistSwapFactory(factory).createPair(address(this), rewardToken_);
        }
        require(pair != address(0), "PAIR_ZERO");
        lpPair = pair;
        _setMandatoryRewardExclusions(pair);

        address twapToken0 = fistUsdtPair.token0();
        address twapToken1 = fistUsdtPair.token1();
        require(
            (twapToken0 == rewardToken_ && twapToken1 == quoteToken_)
                || (twapToken1 == rewardToken_ && twapToken0 == quoteToken_),
            "FIST_USDT_PAIR_MISMATCH"
        );
        usePrice0CumulativeForFistUsdt = twapToken0 == rewardToken_;
        rewardTokenDecimals = rewardToken.decimals();
        quoteTokenDecimals = quoteToken.decimals();

        (uint256 currentPriceCumulative, uint32 currentTimestamp) = _currentFistUsdtCumulativePrice();
        fistUsdtPriceCumulativeLast = currentPriceCumulative;
        fistUsdtBlockTimestampLast = currentTimestamp;
        fistUsdPriceE18 = _currentFistUsdSpotPriceE18();
        lastFistUsdtTwapUpdateTimestamp = block.timestamp;

        isFeeExempt[address(this)] = true;
        isFeeExempt[msg.sender] = true;
        isFeeExempt[marketingWallet_] = true;

        balanceOf[msg.sender] = totalSupply;
        emit Transfer(address(0), msg.sender, totalSupply);
        emit OwnershipTransferred(address(0), msg.sender);
        emit FeeExemptUpdated(address(this), true);
        emit FeeExemptUpdated(msg.sender, true);
        emit FeeExemptUpdated(marketingWallet_, true);
        emit FeeReceiverDeployed(address(feeReceiver));
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        _approve(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        if (allowed != type(uint256).max) {
            allowance[from][msg.sender] = allowed - amount;
        }
        _transfer(from, to, amount);
        return true;
    }

    function enableTrading() external onlyOwner {
        require(!tradingEnabled, "TRADING_ENABLED");
        _startCmsnFistLpTwap();
        tradingEnabled = true;
        liquidityAddedAt = block.timestamp;
        emit TradingEnabled(block.timestamp);
    }

    function setMarketingWallet(address newMarketingWallet) external onlyOwner {
        require(newMarketingWallet != address(0), "MARKETING_ZERO");
        require(newMarketingWallet != FISTSWAP_SINGLE_TAX_HELPER, "HELPER_NOT_FEE_EXEMPT");
        address oldWallet = marketingWallet;
        marketingWallet = newMarketingWallet;
        isFeeExempt[newMarketingWallet] = true;
        emit MarketingWalletUpdated(oldWallet, newMarketingWallet);
        emit FeeExemptUpdated(newMarketingWallet, true);
    }

    function setFeeExempt(address account, bool exempt) external onlyOwner {
        _setFeeExempt(account, exempt);
    }

    function setFeeExemptBatch(address[] calldata accounts_, bool exempt) external onlyOwner {
        for (uint256 i = 0; i < accounts_.length; i++) {
            _setFeeExempt(accounts_[i], exempt);
        }
    }

    function _setFeeExempt(address account, bool exempt) private {
        require(account != lpPair, "PAIR_NOT_EXEMPT");
        require(account != FISTSWAP_SINGLE_TAX_HELPER, "HELPER_NOT_FEE_EXEMPT");
        isFeeExempt[account] = exempt;
        emit FeeExemptUpdated(account, exempt);
    }

    function setRewardExcluded(address account, bool excluded) external onlyOwner {
        _setRewardExcluded(account, excluded);
    }

    function setRewardExcludedBatch(address[] calldata accounts_, bool excluded) external onlyOwner {
        for (uint256 i = 0; i < accounts_.length; i++) {
            _setRewardExcluded(accounts_[i], excluded);
        }
    }

    function _setRewardExcluded(address account, bool excluded) private {
        require(account != address(0), "REWARD_EXCLUDED_ZERO");
        require(excluded || !_isMandatoryRewardExcluded(account), "MANDATORY_REWARD_EXCLUDED");
        if (isRewardExcluded[account] == excluded) return;

        isRewardExcluded[account] = excluded;
        emit RewardExcludedUpdated(account, excluded);

        if (excluded && _isTrackedAccount(accounts[account])) {
            _removeAll(account, "REWARD_EXCLUDED");
            _syncExternalRewardBalance();
        }
    }

    function _setMandatoryRewardExclusions(address pair) private {
        isRewardExcluded[DEAD] = true;
        isRewardExcluded[address(this)] = true;
        isRewardExcluded[address(feeReceiver)] = true;
        isRewardExcluded[pair] = true;
    }

    function setSwapEnabled(bool enabled) external onlyOwner {
        swapEnabled = enabled;
        emit SwapEnabledUpdated(enabled);
    }

    function NORMAL_FEE_BPS() external view returns (uint256) {
        return NORMAL_BURN_BPS + NORMAL_MARKETING_BPS + NORMAL_REWARD_BPS;
    }

    function setFeeSwitches(bool feesEnabled_, bool transferTaxEnabled_, bool ammTaxEnabled_) external onlyOwner {
        feesEnabled = feesEnabled_;
        transferTaxEnabled = transferTaxEnabled_;
        ammTaxEnabled = ammTaxEnabled_;
    }

    function setFeeConfig(
        uint256 normalBurnBps,
        uint256 normalMarketingBps,
        uint256 normalRewardBps,
        uint256 launchBuyFeeBps,
        uint256 launchSellFeeBps,
        uint256 launchDuration
    ) external onlyOwner {
        require(normalBurnBps + normalMarketingBps + normalRewardBps <= FEE_DENOMINATOR, "NORMAL_FEE_TOO_HIGH");
        require(launchBuyFeeBps <= FEE_DENOMINATOR, "LAUNCH_BUY_TOO_HIGH");
        require(launchSellFeeBps <= FEE_DENOMINATOR, "LAUNCH_SELL_TOO_HIGH");

        NORMAL_BURN_BPS = normalBurnBps;
        NORMAL_MARKETING_BPS = normalMarketingBps;
        NORMAL_REWARD_BPS = normalRewardBps;
        LAUNCH_BUY_FEE_BPS = launchBuyFeeBps;
        LAUNCH_SELL_FEE_BPS = launchSellFeeBps;
        LAUNCH_DURATION = launchDuration;
    }

    function setRewardConfig(
        uint256 minLpUsdE18,
        uint256 minHoldingTokenAmount,
        uint256 activationDelay,
        uint256 additionalLpDelay
    ) external onlyOwner {
        MIN_LP_USD_E18 = minLpUsdE18;
        MIN_HOLDING_TOKEN_AMOUNT = minHoldingTokenAmount;
        ACTIVATION_DELAY = activationDelay;
        ADDITIONAL_LP_DELAY = additionalLpDelay;
    }

    function setProcessFeesConfig(
        uint256 swapThreshold,
        uint256 maxSwapPerProcess,
        uint256 manualProcessCooldown,
        uint256 swapMinOutBps
    ) external onlyOwner {
        require(swapThreshold > 0, "BAD_THRESHOLD");
        require(maxSwapPerProcess >= swapThreshold, "BAD_MAX_SWAP");
        require(swapMinOutBps <= FEE_DENOMINATOR, "BAD_MIN_OUT");

        SWAP_THRESHOLD = swapThreshold;
        MAX_SWAP_PER_PROCESS = maxSwapPerProcess;
        MANUAL_PROCESS_COOLDOWN = manualProcessCooldown;
        SWAP_MIN_OUT_BPS = swapMinOutBps;
    }

    function setTwapPeriods(uint256 fistUsdtTwapPeriod, uint256 cmsnFistLpTwapPeriod) external onlyOwner {
        require(fistUsdtTwapPeriod > 0 && cmsnFistLpTwapPeriod > 0, "BAD_TWAP");

        FIST_USDT_TWAP_PERIOD = fistUsdtTwapPeriod;
        CMSN_FIST_LP_TWAP_PERIOD = cmsnFistLpTwapPeriod;
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "OWNER_ZERO");
        address oldOwner = owner;
        owner = newOwner;
        emit OwnershipTransferred(oldOwner, newOwner);
    }

    function processFees() external nonReentrant {
        require(msg.sender == address(this) || msg.sender == marketingWallet, "NOT_MARKETING_WALLET");
        _processFees(msg.sender != address(this));
    }

    function register(address user) external nonReentrant {
        _syncAccount(user, true);
    }

    function batchRegister(address[] calldata users) external nonReentrant {
        for (uint256 i = 0; i < users.length; i++) {
            _syncAccount(users[i], true);
        }
    }

    function sync(address user) external nonReentrant {
        _syncAccount(user, false);
    }

    function batchSync(address[] calldata users) external nonReentrant {
        for (uint256 i = 0; i < users.length; i++) {
            _syncAccount(users[i], false);
        }
    }

    function remove(address user) external nonReentrant {
        _syncAccount(user, false);
    }

    function batchRemove(address[] calldata users) external nonReentrant {
        for (uint256 i = 0; i < users.length; i++) {
            _syncAccount(users[i], false);
        }
    }

    function claim(address user) external nonReentrant returns (uint256) {
        return _claim(user);
    }

    function batchClaim(address[] calldata users) external nonReentrant returns (uint256[] memory amounts) {
        amounts = new uint256[](users.length);
        for (uint256 i = 0; i < users.length; i++) {
            amounts[i] = _claim(users[i]);
        }
    }

    function syncRewards() external nonReentrant returns (uint256) {
        return _syncExternalRewardBalance();
    }

    function updateTwaps() external nonReentrant returns (bool fistUsdtUpdated, bool cmsnFistLpUpdated) {
        fistUsdtUpdated = _tryUpdateFistUsdtTwap();
        cmsnFistLpUpdated = _tryUpdateCmsnFistLpTwap();
    }

    function recordedLP(address user) external view returns (uint256) {
        Account storage account = accounts[user];
        return account.eligibleLP + account.pendingLP;
    }

    function rewardAuditQueueLength() external view returns (uint256) {
        return rewardAuditQueue.length;
    }

    function getRewardStatusBatch(address[] calldata users) external view returns (RewardStatus[] memory statuses) {
        statuses = new RewardStatus[](users.length);
        (bool lpValueReady, uint256 lpUsdPerLpE18) = _tryLpUsdPerLpE18();
        for (uint256 i = 0; i < users.length; i++) {
            statuses[i] = _getRewardStatus(users[i], lpValueReady, lpUsdPerLpE18);
        }
    }

    function getRewardAuditQueuePage(uint256 start, uint256 limit) external view returns (address[] memory users) {
        uint256 queueLength = rewardAuditQueue.length;
        if (start >= queueLength || limit == 0) return new address[](0);

        uint256 remaining = queueLength - start;
        uint256 size = limit < remaining ? limit : remaining;
        users = new address[](size);
        for (uint256 i = 0; i < size; i++) {
            users[i] = rewardAuditQueue[start + i];
        }
    }

    function compactRewardAuditQueue(uint256 limit) external nonReentrant returns (uint256 removed) {
        uint256 queueLength = rewardAuditQueue.length;
        if (queueLength == 0 || limit == 0) return 0;

        uint256 cursor = rewardAuditCursor;
        if (cursor >= queueLength) cursor = 0;

        uint256 checked;
        while (checked < limit && queueLength > 0) {
            if (cursor >= queueLength) cursor = 0;

            address user = rewardAuditQueue[cursor];
            checked++;

            if (user == address(0) || !_isTrackedAccount(accounts[user])) {
                inRewardAuditQueue[user] = false;
                uint256 lastIndex = queueLength - 1;
                if (cursor != lastIndex) {
                    rewardAuditQueue[cursor] = rewardAuditQueue[lastIndex];
                }
                rewardAuditQueue.pop();
                queueLength--;
                removed++;
            } else {
                cursor++;
            }
        }

        rewardAuditCursor = queueLength == 0 ? 0 : cursor % queueLength;
        emit RewardAuditQueueCompacted(checked, removed, queueLength);
    }

    function isTracked(address user) public view returns (bool) {
        Account storage account = accounts[user];
        return _isTrackedAccount(account);
    }

    function lpValueUsdE18(uint256 lpAmount) public view returns (uint256) {
        if (lpAmount == 0) return 0;

        uint256 fistPerLpE18 = _effectiveCmsnFistLpFistPerLpE18();
        uint256 userFistSideE18 = lpAmount * fistPerLpE18 / 1e18;
        require(fistUsdPriceE18 != 0, "TWAP_NOT_READY");
        return userFistSideE18 * fistUsdPriceE18 * 2 / 1e18;
    }

    function _getRewardStatus(address user, bool lpValueReady, uint256 lpUsdPerLpE18)
        private
        view
        returns (RewardStatus memory status)
    {
        Account storage account = accounts[user];
        status.tokenBalance = balanceOf[user];
        status.lpBalance = ICmsnFistSwapPair(lpPair).balanceOf(user);
        status.eligibleLP = account.eligibleLP;
        status.pendingLP = account.pendingLP;
        status.pendingUnlockAt = account.pendingUnlockAt;
        status.pendingRewards = account.pendingRewards;
        status.recordedLP = account.eligibleLP + account.pendingLP;
        status.tracked = _isTrackedAccount(account);
        status.inQueue = inRewardAuditQueue[user];
        status.rewardExcluded = isRewardExcluded[user];

        bool hasMinimumHolding = status.tokenBalance > MIN_HOLDING_TOKEN_AMOUNT;
        uint256 currentLpValue = lpValueReady ? status.lpBalance * lpUsdPerLpE18 / 1e18 : 0;
        uint256 eligibleLpValue = lpValueReady ? status.eligibleLP * lpUsdPerLpE18 / 1e18 : 0;
        uint256 afterActivationLpValue = lpValueReady ? status.recordedLP * lpUsdPerLpE18 / 1e18 : 0;

        status.canRegister = user != address(0) && !status.rewardExcluded && !status.tracked && hasMinimumHolding
            && currentLpValue >= MIN_LP_USD_E18;
        // This read-only flag mirrors the timestamp-based LP eligibility delay.
        // forge-lint: disable-next-line(block-timestamp)
        bool pendingMature = block.timestamp >= status.pendingUnlockAt;
        status.canActivate = !status.rewardExcluded && status.pendingLP != 0 && pendingMature && hasMinimumHolding
            && status.lpBalance != 0 && afterActivationLpValue >= MIN_LP_USD_E18;

        if (status.tracked) {
            if (status.rewardExcluded || !hasMinimumHolding || status.lpBalance == 0) {
                status.shouldRemove = true;
            } else if (lpValueReady) {
                status.shouldRemove = (status.eligibleLP > 0 && eligibleLpValue < MIN_LP_USD_E18)
                    || (status.eligibleLP == 0 && status.pendingLP > 0 && currentLpValue < MIN_LP_USD_E18);
            }
        }

        if (!status.rewardExcluded && status.eligibleLP > 0 && hasMinimumHolding && eligibleLpValue >= MIN_LP_USD_E18) {
            uint256 indexDelta = accRewardPerShare - account.rewardIndexPaid;
            status.claimable = status.pendingRewards + status.eligibleLP * indexDelta / ACC_PRECISION;
        }
    }

    function _transfer(address from, address to, uint256 amount) private {
        require(from != address(0), "TRANSFER_FROM_ZERO");
        require(to != address(0), "TRANSFER_TO_ZERO");
        require(balanceOf[from] >= amount, "INSUFFICIENT_BALANCE");
        require(tradingEnabled || isFeeExempt[from] || isFeeExempt[to], "TRADING_DISABLED");

        bool helperForwardPath = _isFistSwapHelperForwardPath(from, to);
        uint256 helperForwardAmount = helperForwardPath ? _helperForwardAmount(amount) : 0;
        _tryUpdateTwapsOnAmmTransfer(from, to);
        if (!helperForwardPath) {
            _maybeProcessFees(from, to);
        }

        if (inSwap || isFeeExempt[from] || isFeeExempt[to]) {
            _rawTransfer(from, to, amount);
            return;
        }

        if (helperForwardAmount == amount) {
            fistSwapHelperForwardCredit -= helperForwardAmount;
            _rawTransfer(from, to, amount);
            return;
        }

        if (helperForwardAmount > 0) {
            fistSwapHelperForwardCredit -= helperForwardAmount;
            Fee memory helperExcessFee = _normalFee(amount - helperForwardAmount);
            _applyFeeTransfer(from, to, amount, helperExcessFee);
            return;
        }

        Fee memory fee = _feeForTransfer(from, to, amount);
        if (fee.total == 0) {
            _rawTransfer(from, to, amount);
            return;
        }

        _applyFeeTransfer(from, to, amount, fee);
    }

    function _applyFeeTransfer(address from, address to, uint256 amount, Fee memory fee) private {
        balanceOf[from] -= amount;

        if (fee.burn > 0) {
            balanceOf[DEAD] += fee.burn;
            emit Transfer(from, DEAD, fee.burn);
        }

        uint256 contractFee = fee.contractFee;
        if (contractFee > 0) {
            balanceOf[address(this)] += contractFee;
            pendingFeeTokens += contractFee;
            emit Transfer(from, address(this), contractFee);
        }

        uint256 netAmount = amount - fee.total;
        balanceOf[to] += netAmount;
        emit Transfer(from, to, netAmount);

        if (from == lpPair && to == FISTSWAP_SINGLE_TAX_HELPER && fee.total > 0) {
            fistSwapHelperForwardCredit += netAmount * (FEE_DENOMINATOR + FISTSWAP_HELPER_FORWARD_TOLERANCE_BPS)
                / FEE_DENOMINATOR;
        }
    }

    struct Fee {
        uint256 total;
        uint256 burn;
        uint256 contractFee;
    }

    function _feeForTransfer(address from, address to, uint256 amount) private view returns (Fee memory fee) {
        bool isSell = to == lpPair;
        bool isPairOut = from == lpPair;

        bool isRemoveLiquidity = isPairOut && _isRemovingLiquidity();
        // The 10 minute launch window is intentionally timestamp based; small validator drift is not material here.
        // forge-lint: disable-next-line(block-timestamp)
        bool inLaunchWindow = liquidityAddedAt != 0 && block.timestamp < liquidityAddedAt + LAUNCH_DURATION;

        if (inLaunchWindow && isSell && _isAddingLiquidity()) {
            revert("LP_ADD_DISABLED");
        }

        if (!feesEnabled) return fee;

        if (!isSell && !isPairOut) {
            return transferTaxEnabled ? _normalFee(amount) : fee;
        }

        if (!ammTaxEnabled) return fee;

        if (inLaunchWindow && isSell) {
            fee.contractFee = amount * LAUNCH_SELL_FEE_BPS / FEE_DENOMINATOR;
            fee.total = fee.contractFee;
            return fee;
        }

        if (inLaunchWindow && isPairOut && !isRemoveLiquidity) {
            fee.contractFee = amount * LAUNCH_BUY_FEE_BPS / FEE_DENOMINATOR;
            fee.total = fee.contractFee;
            return fee;
        }

        if (isSell || isPairOut) {
            fee = _normalFee(amount);
        }
    }

    function _normalFee(uint256 amount) private view returns (Fee memory fee) {
        fee.burn = amount * NORMAL_BURN_BPS / FEE_DENOMINATOR;
        fee.contractFee = amount * (NORMAL_MARKETING_BPS + NORMAL_REWARD_BPS) / FEE_DENOMINATOR;
        fee.total = fee.burn + fee.contractFee;
    }

    function _maybeProcessFees(address from, address to) private {
        if (inSwap || !swapEnabled || from == address(this) || from == lpPair || isFeeExempt[from] || isFeeExempt[to]) {
            return;
        }

        if (pendingFeeTokens < SWAP_THRESHOLD || balanceOf[address(this)] < SWAP_THRESHOLD) return;

        uint256 gasForProcess = gasleft();
        if (gasForProcess <= AUTO_PROCESS_GAS_RESERVE) return;

        try this.processFees{gas: gasForProcess - AUTO_PROCESS_GAS_RESERVE}() {} catch {}
    }

    function _tryUpdateTwapsOnAmmTransfer(address from, address to) private {
        if (inSwap || (from != lpPair && to != lpPair)) return;
        _tryUpdateFistUsdtTwap();
        _tryUpdateCmsnFistLpTwap();
    }

    function _isFistSwapHelperForwardPath(address from, address to) private view returns (bool) {
        return tradingEnabled && msg.sender == FISTSWAP_SINGLE_TAX_HELPER && from == FISTSWAP_SINGLE_TAX_HELPER
            && to != lpPair;
    }

    function _helperForwardAmount(uint256 amount) private view returns (uint256) {
        uint256 credit = fistSwapHelperForwardCredit;
        return amount < credit ? amount : credit;
    }

    function _enqueueRewardAudit(address user) private {
        if (user == address(0) || inRewardAuditQueue[user]) return;
        inRewardAuditQueue[user] = true;
        rewardAuditQueue.push(user);
        emit RewardAuditQueued(user);
    }

    function _processFees(bool enforceManualCooldown) private {
        uint256 totalPending = pendingFeeTokens;
        if (totalPending < SWAP_THRESHOLD || balanceOf[address(this)] < SWAP_THRESHOLD) return;

        if (enforceManualCooldown) {
            // Keeper-triggered processing is deliberately timestamp-gated; transaction-triggered processing is not.
            // forge-lint: disable-next-line(block-timestamp)
            require(block.timestamp >= lastManualProcessFeesAt + MANUAL_PROCESS_COOLDOWN, "PROCESS_COOLDOWN");
            lastManualProcessFeesAt = block.timestamp;
        }

        uint256 totalTokens = _maxSwapPerProcess();
        if (totalTokens > totalPending) totalTokens = totalPending;
        uint256 contractBalance = balanceOf[address(this)];
        if (totalTokens > contractBalance) totalTokens = contractBalance;
        if (totalTokens < SWAP_THRESHOLD) return;

        pendingFeeTokens -= totalTokens;

        address receiver = address(feeReceiver);
        uint256 beforeBalance = rewardToken.balanceOf(receiver);
        _approve(address(this), address(router), totalTokens);

        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = address(rewardToken);

        uint256 amountOutMin = _minFistOutForCmsnSwap(totalTokens);

        inSwap = true;
        router.swapExactTokensForTokensSupportingFeeOnTransferTokens(
            totalTokens, amountOutMin, path, receiver, block.timestamp
        );
        inSwap = false;

        uint256 fistReceived = rewardToken.balanceOf(receiver) - beforeBalance;
        if (fistReceived > 0) {
            feeReceiver.sweep(address(rewardToken), address(this), fistReceived);
        }

        (uint256 marketingFist, uint256 rewardFist) = _splitProcessedFist(fistReceived);

        if (marketingFist > 0) {
            _safeTransfer(address(rewardToken), marketingWallet, marketingFist);
        }

        if (rewardFist > 0) {
            _addRewards(rewardFist);
        }

        emit FeesProcessed(totalTokens, marketingFist, rewardFist);
    }

    function _maxSwapPerProcess() private view returns (uint256) {
        // During the launch window fee processing follows the accumulated pending tax without an extra per-call cap.
        // forge-lint: disable-next-line(block-timestamp)
        if (liquidityAddedAt != 0 && block.timestamp < liquidityAddedAt + LAUNCH_DURATION) {
            return type(uint256).max;
        }
        return MAX_SWAP_PER_PROCESS;
    }

    function _splitProcessedFist(uint256 fistReceived)
        private
        view
        returns (uint256 marketingFist, uint256 rewardFist)
    {
        // During the launch window processed fees are launch support funds, so the full FIST output goes to marketing.
        // forge-lint: disable-next-line(block-timestamp)
        if (liquidityAddedAt != 0 && block.timestamp < liquidityAddedAt + LAUNCH_DURATION) {
            return (fistReceived, 0);
        }

        uint256 splitTotal = NORMAL_MARKETING_BPS + NORMAL_REWARD_BPS;
        if (splitTotal == 0) return (fistReceived, 0);
        marketingFist = fistReceived * NORMAL_MARKETING_BPS / splitTotal;
        rewardFist = fistReceived - marketingFist;
    }

    function _rawTransfer(address from, address to, uint256 amount) private {
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        emit Transfer(from, to, amount);
    }

    function _approve(address tokenOwner, address spender, uint256 amount) private {
        require(tokenOwner != address(0), "APPROVE_FROM_ZERO");
        require(spender != address(0), "APPROVE_TO_ZERO");
        allowance[tokenOwner][spender] = amount;
        emit Approval(tokenOwner, spender, amount);
    }

    function _claim(address user) private returns (uint256 amount) {
        _syncAccount(user, false);

        Account storage account = accounts[user];
        if (account.eligibleLP == 0) return 0;
        if (!_hasMinimumHolding(user) || lpValueUsdE18(account.eligibleLP) < MIN_LP_USD_E18) {
            _removeAll(user, "CLAIM_RECHECK_FAILED");
            _syncExternalRewardBalance();
            return 0;
        }

        _settleCurrent(account);
        amount = account.pendingRewards;
        if (amount == 0) return 0;

        account.pendingRewards = 0;
        accountedRewardBalance -= amount;
        _safeTransfer(address(rewardToken), user, amount);
        emit Claimed(user, amount, msg.sender);
    }

    function _syncAccount(address user, bool allowRegister) private {
        if (user == address(0)) return;
        _tryUpdateFistUsdtTwap();
        _tryUpdateCmsnFistLpTwap();

        Account storage account = accounts[user];
        if (isRewardExcluded[user]) {
            if (_isTrackedAccount(account)) {
                _removeAll(user, "REWARD_EXCLUDED");
                _syncExternalRewardBalance();
            }
            return;
        }

        uint256 currentLP = ICmsnFistSwapPair(lpPair).balanceOf(user);
        bool tracked = account.eligibleLP != 0 || account.pendingLP != 0;

        if (!tracked) {
            if (allowRegister && _hasMinimumHolding(user) && lpValueUsdE18(currentLP) >= MIN_LP_USD_E18) {
                account.pendingLP = currentLP;
                account.pendingUnlockAt = block.timestamp + ACTIVATION_DELAY;
                account.rewardIndexPaid = accRewardPerShare;
                _enqueueRewardAudit(user);
                emit PendingRegistered(user, currentLP, account.pendingUnlockAt);
            }
            return;
        }

        if (!_hasMinimumHolding(user) || currentLP == 0) {
            _removeAll(user, "CURRENT_CONDITION_FAILED");
            _syncExternalRewardBalance();
            return;
        }

        uint256 recorded = account.eligibleLP + account.pendingLP;

        if (currentLP < recorded) {
            _applyDecrease(account, user, recorded - currentLP);
            _validateAfterChange(account, user, currentLP);
            _syncExternalRewardBalance();
            _activatePendingIfReady(account, user);
            _validateAfterChange(account, user, currentLP);
            return;
        }

        _syncExternalRewardBalance();
        _activatePendingIfReady(account, user);

        recorded = account.eligibleLP + account.pendingLP;
        if (account.pendingLP == 0 && currentLP > recorded) {
            uint256 increase = currentLP - recorded;
            if (lpValueUsdE18(increase) >= MIN_LP_USD_E18) {
                _addPending(account, user, increase);
            }
        }

        _validateAfterChange(account, user, currentLP);
    }

    function _applyDecrease(Account storage account, address user, uint256 deficit) private {
        if (deficit <= account.pendingLP) {
            account.pendingLP -= deficit;
            if (account.pendingLP == 0) account.pendingUnlockAt = 0;
            emit PendingReduced(user, deficit, account.pendingLP);
            return;
        }

        uint256 pendingRemoved = account.pendingLP;
        deficit -= account.pendingLP;
        account.pendingLP = 0;
        account.pendingUnlockAt = 0;
        if (pendingRemoved > 0) {
            emit PendingReduced(user, pendingRemoved, 0);
        }

        uint256 oldEligible = account.eligibleLP;
        uint256 newEligible = deficit >= oldEligible ? 0 : oldEligible - deficit;
        _settleReduced(account, newEligible);
        totalEligibleLP = totalEligibleLP - oldEligible + newEligible;
        account.eligibleLP = newEligible;
        emit EligibleReduced(user, oldEligible, newEligible);
    }

    function _activatePendingIfReady(Account storage account, address user) private {
        // The LP eligibility delay is intentionally timestamp based and tolerant to small validator drift.
        // forge-lint: disable-next-line(block-timestamp)
        if (account.pendingLP == 0 || block.timestamp < account.pendingUnlockAt) return;

        _settleCurrent(account);
        uint256 amount = account.pendingLP;
        account.pendingLP = 0;
        account.pendingUnlockAt = 0;
        account.eligibleLP += amount;
        totalEligibleLP += amount;
        account.rewardIndexPaid = accRewardPerShare;
        emit Activated(user, amount, account.eligibleLP);
    }

    function _addPending(Account storage account, address user, uint256 amount) private {
        if (amount == 0) return;
        _settleCurrent(account);
        account.pendingLP += amount;
        account.pendingUnlockAt = block.timestamp + ADDITIONAL_LP_DELAY;
        account.rewardIndexPaid = accRewardPerShare;
        _enqueueRewardAudit(user);
        emit PendingIncreased(user, amount, account.pendingLP, account.pendingUnlockAt);
    }

    function _validateAfterChange(Account storage account, address user, uint256 currentLP) private {
        if (!_hasMinimumHolding(user) || currentLP == 0) {
            _removeAll(user, "VALIDATION_FAILED");
            return;
        }

        if (account.eligibleLP > 0 && lpValueUsdE18(account.eligibleLP) < MIN_LP_USD_E18) {
            _removeEligible(account, user, "ELIGIBLE_BELOW_100U");
        }

        if (account.eligibleLP == 0 && account.pendingLP > 0 && lpValueUsdE18(currentLP) < MIN_LP_USD_E18) {
            _removeAll(user, "PENDING_BELOW_100U");
        }
    }

    function _removeEligible(Account storage account, address user, string memory reason) private {
        uint256 oldEligible = account.eligibleLP;
        if (oldEligible == 0) return;

        _settleReduced(account, 0);
        totalEligibleLP -= oldEligible;
        account.eligibleLP = 0;
        uint256 forfeited = _forfeitPendingRewards(account);
        account.rewardIndexPaid = accRewardPerShare;
        emit Removed(user, forfeited, reason);
    }

    function _removeAll(address user, string memory reason) private {
        Account storage account = accounts[user];
        uint256 oldEligible = account.eligibleLP;
        uint256 forfeited;

        if (oldEligible > 0) {
            _settleReduced(account, 0);
            totalEligibleLP -= oldEligible;
        }

        forfeited += _forfeitPendingRewards(account);
        account.eligibleLP = 0;
        account.pendingLP = 0;
        account.pendingUnlockAt = 0;
        account.rewardIndexPaid = accRewardPerShare;
        emit Removed(user, forfeited, reason);
    }

    function _settleCurrent(Account storage account) private {
        uint256 indexDelta = accRewardPerShare - account.rewardIndexPaid;
        if (indexDelta > 0 && account.eligibleLP > 0) {
            account.pendingRewards += account.eligibleLP * indexDelta / ACC_PRECISION;
        }
        account.rewardIndexPaid = accRewardPerShare;
    }

    function _settleReduced(Account storage account, uint256 newEligibleLP) private {
        uint256 indexDelta = accRewardPerShare - account.rewardIndexPaid;
        if (indexDelta > 0 && account.eligibleLP > 0) {
            uint256 oldEarned = account.eligibleLP * indexDelta / ACC_PRECISION;
            uint256 keptEarned = newEligibleLP * indexDelta / ACC_PRECISION;
            account.pendingRewards += keptEarned;
            if (oldEarned > keptEarned) {
                _makeRewardsUnaccounted(oldEarned - keptEarned);
            }
        }
        account.rewardIndexPaid = accRewardPerShare;
    }

    function _forfeitPendingRewards(Account storage account) private returns (uint256 forfeited) {
        forfeited = account.pendingRewards;
        if (forfeited > 0) {
            account.pendingRewards = 0;
            _makeRewardsUnaccounted(forfeited);
        }
    }

    function _syncExternalRewardBalance() private returns (uint256 distributed) {
        uint256 currentBalance = rewardToken.balanceOf(address(this));
        if (currentBalance <= accountedRewardBalance) return 0;
        uint256 delta = currentBalance - accountedRewardBalance;
        return _addRewards(delta);
    }

    function _addRewards(uint256 amount) private returns (uint256 distributed) {
        if (amount == 0) return 0;

        if (totalEligibleLP == 0) {
            redirectedRewards += amount;
            _safeTransfer(address(rewardToken), marketingWallet, amount);
            emit RewardsRedirected(amount);
            return 0;
        }

        uint256 indexDelta = amount * ACC_PRECISION / totalEligibleLP;
        if (indexDelta == 0) {
            redirectedRewards += amount;
            _safeTransfer(address(rewardToken), marketingWallet, amount);
            emit RewardsRedirected(amount);
            return 0;
        }

        distributed = indexDelta * totalEligibleLP / ACC_PRECISION;
        uint256 dust = amount - distributed;
        if (dust > 0) {
            redirectedRewards += dust;
            _safeTransfer(address(rewardToken), marketingWallet, dust);
            emit RewardsRedirected(dust);
        }
        accountedRewardBalance += distributed;
        accRewardPerShare += indexDelta;
        emit RewardsSynced(distributed, indexDelta);
    }

    function _tryUpdateFistUsdtTwap() private returns (bool updated) {
        (bool ok, uint256 newPrice, uint256 currentPriceCumulative, uint32 currentTimestamp, uint32 timeElapsed) =
            _calculateFistUsdtTwap();
        if (ok) {
            _storeFistUsdtTwap(newPrice, currentPriceCumulative, currentTimestamp, timeElapsed);
            return true;
        }
    }

    function _calculateFistUsdtTwap()
        private
        view
        returns (bool ok, uint256 priceE18, uint256 currentPriceCumulative, uint32 currentTimestamp, uint32 timeElapsed)
    {
        (currentPriceCumulative, currentTimestamp) = _currentFistUsdtCumulativePrice();
        unchecked {
            timeElapsed = currentTimestamp - fistUsdtBlockTimestampLast;
        }

        if (timeElapsed < FIST_USDT_TWAP_PERIOD || currentPriceCumulative <= fistUsdtPriceCumulativeLast) {
            return (false, 0, currentPriceCumulative, currentTimestamp, timeElapsed);
        }

        uint256 averageX112 = (currentPriceCumulative - fistUsdtPriceCumulativeLast) / timeElapsed;
        uint256 quoteRawPerOneFist = averageX112 * (10 ** rewardTokenDecimals) / Q112;
        priceE18 = _scaleTo18(quoteRawPerOneFist, quoteTokenDecimals);
        ok = priceE18 != 0;
    }

    function _storeFistUsdtTwap(
        uint256 priceE18,
        uint256 currentPriceCumulative,
        uint32 currentTimestamp,
        uint32 timeElapsed
    ) private {
        fistUsdPriceE18 = priceE18;
        fistUsdtPriceCumulativeLast = currentPriceCumulative;
        fistUsdtBlockTimestampLast = currentTimestamp;
        lastFistUsdtTwapUpdateTimestamp = block.timestamp;
        emit FistUsdtTwapUpdated(priceE18, timeElapsed);
    }

    function _startCmsnFistLpTwap() private {
        uint256 currentFistPerLpE18 = _currentCmsnFistLpFistPerLpE18();
        require(currentFistPerLpE18 != 0, "LP_TWAP_NOT_READY");

        uint32 currentTimestamp = _currentBlockTimestamp();
        cmsnFistLpFistPerLpCumulative = 0;
        cmsnFistLpObservationTimestampLast = currentTimestamp;
        cmsnFistLpFistPerLpLastE18 = currentFistPerLpE18;
        cmsnFistLpTwapCumulativeLast = 0;
        cmsnFistLpTwapTimestampLast = currentTimestamp;
        cmsnFistLpFistPerLpTwapE18 = 0;
        lastCmsnFistLpTwapUpdateTimestamp = 0;
    }

    function _tryUpdateCmsnFistLpTwap() private returns (bool updated) {
        if (cmsnFistLpObservationTimestampLast == 0) return false;
        _observeCmsnFistLp();

        uint32 timeElapsed;
        unchecked {
            timeElapsed = cmsnFistLpObservationTimestampLast - cmsnFistLpTwapTimestampLast;
        }
        if (timeElapsed < CMSN_FIST_LP_TWAP_PERIOD) return false;

        uint256 cumulativeDelta = cmsnFistLpFistPerLpCumulative - cmsnFistLpTwapCumulativeLast;
        uint256 averageFistPerLpE18 = cumulativeDelta / timeElapsed;
        if (averageFistPerLpE18 == 0) return false;

        _storeCmsnFistLpTwap(averageFistPerLpE18, timeElapsed);
        return true;
    }

    function _storeCmsnFistLpTwap(uint256 averageFistPerLpE18, uint32 timeElapsed) private {
        cmsnFistLpFistPerLpTwapE18 = averageFistPerLpE18;
        cmsnFistLpTwapCumulativeLast = cmsnFistLpFistPerLpCumulative;
        cmsnFistLpTwapTimestampLast = cmsnFistLpObservationTimestampLast;
        lastCmsnFistLpTwapUpdateTimestamp = block.timestamp;

        emit CmsnFistLpTwapUpdated(averageFistPerLpE18, timeElapsed);
    }

    function _observeCmsnFistLp() private {
        uint32 currentTimestamp = _currentBlockTimestamp();
        uint32 previousTimestamp = cmsnFistLpObservationTimestampLast;

        if (previousTimestamp != 0) {
            uint32 timeElapsed;
            unchecked {
                timeElapsed = currentTimestamp - previousTimestamp;
            }
            if (timeElapsed > 0) {
                cmsnFistLpFistPerLpCumulative += cmsnFistLpFistPerLpLastE18 * timeElapsed;
                cmsnFistLpObservationTimestampLast = currentTimestamp;
            }
        } else {
            cmsnFistLpObservationTimestampLast = currentTimestamp;
        }

        cmsnFistLpFistPerLpLastE18 = _currentCmsnFistLpFistPerLpE18();
    }

    function _currentCmsnFistLpFistPerLpE18() private view returns (uint256) {
        uint256 supply = ICmsnFistSwapPair(lpPair).totalSupply();
        if (supply == 0) return 0;

        uint256 fistReserve = _pairFistReserve();
        if (fistReserve == 0) return 0;

        uint256 fistReserveE18 = _scaleTo18(fistReserve, rewardTokenDecimals);
        return fistReserveE18 * 1e18 / supply;
    }

    function _effectiveCmsnFistLpFistPerLpE18() private view returns (uint256) {
        uint256 twapFistPerLpE18 = cmsnFistLpFistPerLpTwapE18;
        require(twapFistPerLpE18 != 0, "LP_TWAP_NOT_READY");

        uint256 currentFistPerLpE18 = _currentCmsnFistLpFistPerLpE18();
        if (currentFistPerLpE18 == 0) return 0;
        return currentFistPerLpE18 < twapFistPerLpE18 ? currentFistPerLpE18 : twapFistPerLpE18;
    }

    function _tryLpUsdPerLpE18() private view returns (bool ok, uint256 lpUsdPerLpE18) {
        uint256 twapFistPerLpE18 = cmsnFistLpFistPerLpTwapE18;
        uint256 fistPriceE18 = fistUsdPriceE18;
        if (twapFistPerLpE18 == 0 || fistPriceE18 == 0) return (false, 0);

        uint256 currentFistPerLpE18 = _currentCmsnFistLpFistPerLpE18();
        if (currentFistPerLpE18 == 0) return (true, 0);

        uint256 fistPerLpE18 = currentFistPerLpE18 < twapFistPerLpE18 ? currentFistPerLpE18 : twapFistPerLpE18;
        lpUsdPerLpE18 = fistPerLpE18 * fistPriceE18 * 2 / 1e18;
        ok = true;
    }

    function _currentFistUsdSpotPriceE18() private view returns (uint256) {
        (uint112 reserve0, uint112 reserve1,) = fistUsdtPair.getReserves();
        require(reserve0 > 0 && reserve1 > 0, "FIST_USDT_EMPTY");

        uint256 quoteRawPerOneFist = usePrice0CumulativeForFistUsdt
            ? uint256(reserve1) * (10 ** rewardTokenDecimals) / uint256(reserve0)
            : uint256(reserve0) * (10 ** rewardTokenDecimals) / uint256(reserve1);
        uint256 priceE18 = _scaleTo18(quoteRawPerOneFist, quoteTokenDecimals);
        require(priceE18 != 0, "FIST_USD_ZERO");
        return priceE18;
    }

    function _currentFistUsdtCumulativePrice() private view returns (uint256 priceCumulative, uint32 currentTimestamp) {
        priceCumulative =
            usePrice0CumulativeForFistUsdt ? fistUsdtPair.price0CumulativeLast() : fistUsdtPair.price1CumulativeLast();
        (uint112 reserve0, uint112 reserve1, uint32 reserveTimestamp) = fistUsdtPair.getReserves();
        currentTimestamp = _currentBlockTimestamp();

        uint32 timeElapsed;
        unchecked {
            timeElapsed = currentTimestamp - reserveTimestamp;
        }

        if (timeElapsed > 0 && reserve0 > 0 && reserve1 > 0) {
            uint256 currentPriceX112 = usePrice0CumulativeForFistUsdt
                ? (uint256(reserve1) * Q112) / reserve0
                : (uint256(reserve0) * Q112) / reserve1;
            priceCumulative += currentPriceX112 * timeElapsed;
        }
    }

    function _isAddingLiquidity() private view returns (bool) {
        uint256 fistBalance = rewardToken.balanceOf(lpPair);
        uint256 fistReserve = _pairFistReserve();
        return fistBalance > fistReserve;
    }

    function _isRemovingLiquidity() private view returns (bool) {
        uint256 fistBalance = rewardToken.balanceOf(lpPair);
        uint256 fistReserve = _pairFistReserve();
        return fistBalance < fistReserve;
    }

    function _pairFistReserve() private view returns (uint256) {
        (uint112 reserve0, uint112 reserve1,) = ICmsnFistSwapPair(lpPair).getReserves();
        return ICmsnFistSwapPair(lpPair).token0() == address(rewardToken) ? uint256(reserve0) : uint256(reserve1);
    }

    function _minFistOutForCmsnSwap(uint256 amountIn) private view returns (uint256) {
        (uint112 reserve0, uint112 reserve1,) = ICmsnFistSwapPair(lpPair).getReserves();
        bool cmsnIsToken0 = ICmsnFistSwapPair(lpPair).token0() == address(this);
        uint256 reserveIn = cmsnIsToken0 ? uint256(reserve0) : uint256(reserve1);
        uint256 reserveOut = cmsnIsToken0 ? uint256(reserve1) : uint256(reserve0);
        require(reserveIn > 0 && reserveOut > 0, "SWAP_PAIR_EMPTY");

        uint256 amountInWithFee = amountIn * 997;
        uint256 expectedOut = amountInWithFee * reserveOut / (reserveIn * 1000 + amountInWithFee);
        uint256 minOut = expectedOut * SWAP_MIN_OUT_BPS / FEE_DENOMINATOR;
        require(minOut > 0, "SWAP_MIN_OUT_ZERO");
        return minOut;
    }

    function _makeRewardsUnaccounted(uint256 amount) private {
